<div class="adm-table-wrap" style="background:#fff;border:1px solid #ececec;border-radius:12px"><table class="tcm-table"><thead><tr><th>Student</th><th>Partner</th><th>Course / Batch</th><th>Consent</th><th>Status</th><th>Review</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="6">No attributed student records.</td></tr><?php endif ?><?php foreach($rows as $r): ?><tr><td><?= e($r['name']) ?><br><span class="muted"><?= e($r['email']) ?></span></td><td><?= e($r['display_name']) ?></td><td><?= e($r['course_title']??'—') ?><br><?= e($r['batch_name']??'') ?></td><td><?= $r['consent_at']?e($r['consent_at']):'Not recorded' ?></td><td><?= e(str_replace('_',' ',$r['status'])) ?></td><td><form method="post" action="<?= base_url('/admin/partners/students/'.$r['id']) ?>"><?= csrf_field() ?><select name="status" class="form-select form-select-sm"><option value="lead">Lead</option><option value="admission_pending">Admission pending</option><option value="enrolled">Enrolled</option><option value="active">Active</option><option value="completed">Completed</option><option value="dropped">Dropped</option><option value="rejected">Reject</option></select><button class="tcm-btn primary sm">Save</button></form></td></tr><?php endforeach ?></tbody></table></div>
